<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {api,PageHeader,Feedback,EmptyState,StatusBadge,useCommand,session,type DataRow} from '@tradeflow/ui'
import {useRows,text} from '../data'
import Pagination from '../components/Pagination.vue'
const list=useRows(()=>'/api/v1/admin/users'),command=useCommand('admin-users')
const modal=ref(''),target=ref(''),username=ref(''),status=ref('ACTIVE'),roles=ref<string[]>([]),merchantId=ref(''),memberRole=ref('OPERATOR'),reason=ref(''),localError=ref(''),notice=ref('')
let generation=0
onBeforeUnmount(()=>{generation++})
function open(kind:string,user:DataRow={}){generation++;modal.value=kind;target.value=String(user.userId||'');username.value=String(user.username||'');status.value=String(user.status||'ACTIVE');roles.value=Array.isArray(user.roles)?user.roles.map(String):['USER'];merchantId.value=String(user.merchantId||'');memberRole.value=user.role==='ADMIN'?'ADMIN':'OPERATOR';reason.value='';localError.value=''}
function close(){generation++;modal.value=''}
/** 平台全局角色与每店职级分别维护；恢复须显式指定真实商家和目标职级，原因随授权及令牌撤销同事务审计。 */
async function submit(){localError.value='';if(!reason.value.trim()){localError.value='请填写平台操作原因';return}if(!/^[1-9][0-9]{0,18}$/.test(target.value)){localError.value='请填写合法的目标用户编号';return}if(modal.value==='member'&&!/^merchant_[a-z0-9_]{1,48}$/.test(merchantId.value)){localError.value='请填写合法的目标商家编号';return}if(modal.value==='roles'&&!roles.value.length){localError.value='至少保留一个角色';return}const kind=modal.value,g=generation;let path='/api/v1/admin/users/'+target.value,method='PATCH',body:DataRow={status:status.value,reason:reason.value.trim()};if(kind==='roles'){path+='/roles';method='PUT';body={roles:[...roles.value],reason:reason.value.trim()}}if(kind==='member'){path='/api/v1/admin/merchant-members';method='POST';body={userId:target.value,merchantId:merchantId.value,role:memberRole.value,status:status.value,reason:reason.value.trim()}}const result=await command.run(kind+':'+target.value+(kind==='member'?':'+merchantId.value:''),body,key=>api(path,{method,body,key}));if(g!==generation||result===undefined)return;await command.reset();if(g!==generation)return;modal.value='';notice.value='账号管理请求已返回，请核对最新状态；变更授权后目标账号需重新登录。';await list.reload()}
watch(()=>session.user?.userId,()=>{close();list.clear();notice.value=''})
onMounted(()=>list.reload())
</script>
<template><PageHeader title="账号与权限" description="维护账号状态、完整角色集合及商家成员关系，所有操作保留原因。"><template #actions><ElButton type="primary" @click="open('member')">维护商家成员</ElButton></template></PageHeader><p v-if="notice" class="notice success-note" role="status">{{notice}}</p><section class="panel"><div class="toolbar"><h2>用户账号</h2><ElButton :loading="list.loading.value" @click="list.reload">刷新列表</ElButton></div><Feedback :loading="list.loading.value" :error="list.error.value"/><template v-if="!list.loading.value&&!list.error.value"><EmptyState v-if="!list.items.value.length" title="当前页暂无用户"/><ElTable v-else :data="list.items.value"><ElTableColumn prop="userId" label="用户编号" min-width="140"/><ElTableColumn prop="username" label="登录账号" min-width="160"/><ElTableColumn prop="displayName" label="显示名称" min-width="150"/><ElTableColumn label="状态" width="120"><template #default="{row}"><StatusBadge :status="text(row.status)"/></template></ElTableColumn><ElTableColumn label="当前角色" min-width="220"><template #default="{row}">{{Array.isArray(row.roles)?row.roles.join(' / '):'—'}}</template></ElTableColumn><ElTableColumn label="操作" min-width="230"><template #default="{row}"><ElButton @click="open('status',row)">修改状态</ElButton><ElButton @click="open('roles',row)">分配角色</ElButton></template></ElTableColumn></ElTable></template><Pagination :page="list.page.value" :count="list.items.value.length" :total="list.total.value" :has-next="list.hasNext.value" :loading="list.loading.value" @change="list.change"/></section>
<ElDialog :model-value="!!modal" :title="modal==='member'?'维护商家成员':modal==='roles'?'完整角色分配':'修改账号状态'" width="620px" @close="close"><ElForm label-position="top" @submit.prevent="submit"><p v-if="modal!=='member'" class="notice">目标：{{username}}（{{target}}）</p><template v-if="modal==='member'"><ElFormItem label="目标用户编号" required><ElInput v-model="target" inputmode="numeric"/></ElFormItem><ElFormItem label="目标商家编号" required><ElInput v-model.trim="merchantId" maxlength="57" placeholder="merchant_开头的实际商家编号"/></ElFormItem><ElFormItem label="本商家职级" required><ElSelect v-model="memberRole"><ElOption label="管理员" value="ADMIN"/><ElOption label="操作员" value="OPERATOR"/></ElSelect></ElFormItem><p class="field-hint">请输入目标账号和实际商家编号。本次将按所选职级和状态维护该店成员；历史无有效管理员的商家，可为有效账号补授管理员。全局商家角色不授予每店权限，不能移除最后一个有效管理员。</p></template><ElFormItem v-if="modal!=='roles'" :label="modal==='member'?'成员状态':'账号状态'" required><ElSelect v-model="status"><ElOption label="启用" value="ACTIVE"/><ElOption label="停用" value="DISABLED"/></ElSelect></ElFormItem><ElFormItem v-else label="完整角色集合（将替换现有角色）" required><ElCheckboxGroup v-model="roles"><ElCheckbox label="USER">普通用户</ElCheckbox><ElCheckbox label="MERCHANT_OPERATOR">商家操作员</ElCheckbox><ElCheckbox label="MERCHANT_ADMIN">商家管理员</ElCheckbox><ElCheckbox label="PLATFORM_ADMIN">平台管理员</ElCheckbox></ElCheckboxGroup></ElFormItem><ElFormItem label="操作原因" required><ElInput v-model="reason" type="textarea" :rows="3" maxlength="500"/></ElFormItem><Feedback :error="localError||command.error.value"/><ElButton native-type="submit" type="primary" :loading="command.busy.value">确认提交</ElButton><ElButton @click="close">关闭</ElButton></ElForm></ElDialog></template>
